#!/usr/bin/env bash
# DSH WorkBuddy XD Pool v1.9.20 Linux/macOS one-click installer.
# The payload below is a gzip-compressed tar archive of the offline plugin tree.
set -euo pipefail

VERSION='1.9.20'
PACKAGE="DSH-Workbuddy-Purge-v${VERSION}"
DSH_HOME="${DSH_HOME:-$HOME/.dsh}"
BASE="$DSH_HOME/plugin-packages"
DEST="$BASE/$PACKAGE"
EXTRACT_ONLY=0

case "${1:-}" in
  --extract-only|--no-install) EXTRACT_ONLY=1 ;;
  -h|--help)
    printf 'Usage: bash %s [--extract-only]\n' "$0"
    exit 0
    ;;
esac

info() { printf '>> %s\n' "$*"; }
ok()   { printf '   [OK] %s\n' "$*"; }
err()  { printf '   [X] %s\n' "$*"; }

if ! command -v python3 >/dev/null 2>&1; then
  err "python3 is required to decode this installer"
  exit 1
fi
if ! command -v tar >/dev/null 2>&1; then
  err "tar is required to extract this installer"
  exit 1
fi

mkdir -p "$BASE"
if [[ -e "$DEST" || -L "$DEST" ]]; then
  BACKUP="${DEST}.bak-$(date +%Y%m%d-%H%M%S)-$$"
  mv "$DEST" "$BACKUP"
  ok "existing package moved to $BACKUP"
fi
mkdir -p "$DEST"

PAYLOAD="$(mktemp)"
trap 'rm -f "$PAYLOAD"' EXIT

info "extracting $PACKAGE to $DEST"
python3 -c 'import sys,base64; sys.stdout.buffer.write(base64.b64decode(sys.stdin.buffer.read()))' <<'__DSH_WORKBUDDY_PAYLOAD__' > "$PAYLOAD"
