__DSH_WORKBUDDY_PAYLOAD__
tar -xzf "$PAYLOAD" -C "$DEST"

if [[ ! -f "$DEST/install-linux.sh" ]]; then
  err "payload is missing install-linux.sh"
  exit 1
fi
chmod +x "$DEST/install-linux.sh" 2>/dev/null || true
ok "payload extracted"

if (( EXTRACT_ONLY )); then
  ok "extract-only mode; installer step skipped"
  printf 'Package directory: %s\n' "$DEST"
  exit 0
fi

info "running install-linux.sh"
bash "$DEST/install-linux.sh"
